CREATE OR REPLACE FUNCTION ECAMS.SVRJOBCHK
(SYSCD IN VARCHAR2,SVRCD IN VARCHAR2,SVRSEQ IN INTEGER,JOBCD IN VARCHAR2)


RETURN NUMBER
IS
    CNTVAL NUMBER := 0;

-- 리턴값 0:처리 1:미처리
-- 업무별서버관리하는 경우 사용
-- 해당서버가 해당업무에서 사용하는지 여부
BEGIN
    SELECT count(*)
      INTO CNTVAL
      FROM CMM0035 C
     WHERE C.CM_SYSCD  = SYSCD
       AND C.CM_SVRCD  = SVRCD
       AND C.CM_SEQNO  = SVRSEQ
       AND C.CM_JOBCD  = JOBCD;

    IF CNTVAL > 0 THEN
        return 0;
    ELSE
        return 1;
    END IF;

end;